const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry (Bobiri Forest Reserve, Ghana)
  // Try to get from WDPA; fallback to point + buffer
  var wdpa = ee.FeatureCollection("WCMC/WDPA/current/polygons");
  var bobiri = wdpa.filter(ee.Filter.and(
    ee.Filter.eq("NAME", "Bobiri Forest Reserve"),
    ee.Filter.eq("ISO3", "GHA")
  ));
  var geometry = bobiri;
  // If WDPA fails, use a point near Bobiri (6.7167° N, 1.3333° W) buffered by 5km
  var fallbackPoint = ee.Geometry.Point([-1.3333, 6.7167]);
  var fallbackGeometry = fallbackPoint.buffer(5000);
  // Use the first feature from WDPA or fallback
  geometry = ee.Algorithms.If({
    condition: bobiri.size(),
    trueCase: bobiri.geometry(),
    falseCase: fallbackGeometry
  });
  geometry = ee.Geometry(geometry);

  // 2. Define years and bands
  var start2003 = '2003-01-01';
  var end2003 = '2003-12-31';
  var start2023 = '2023-01-01';
  var end2023 = '2023-12-31';

  // 3. Try MODIS land cover (MCD12Q1) for forest classification (IGBP classes 1-5)
  var modis2003 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate(start2003, end2003)
    .select('LC_Type1');
  var modis2023 = ee.ImageCollection('MODIS/006/MCD12Q1')
    .filterDate(start2023, end2023)
    .select('LC_Type1');

  // Check collection sizes
  var modis2003Size = modis2003.size().getInfo();
  var modis2023Size = modis2023.size().getInfo();
  console.log(`2003 MODIS images: ${modis2003Size}`);
  console.log(`2023 MODIS images: ${modis2023Size}`);

  // If either collection is empty, try Hansen dataset as fallback
  var useHansen = false;
  if (modis2003Size === 0 || modis2023Size === 0) {
    console.log('MODIS data missing for one or both years, switching to Hansen dataset.');
    useHansen = true;
  }

  var forest2003, forest2023;
  if (!useHansen) {
    // Use MODIS: forest = IGBP classes 1-5
    var modisImg2003 = modis2003.mosaic().clip(geometry);
    var modisImg2023 = modis2023.mosaic().clip(geometry);
    forest2003 = modisImg2003.gte(1).and(modisImg2003.lte(5)).selfMask();
    forest2023 = modisImg2023.gte(1).and(modisImg2023.lte(5)).selfMask();
  } else {
    // Use Hansen dataset: forest = tree cover > 30%
    var hansen = ee.Image('UMD/hansen/global_forest_change_2022_v1_10');
    var treeCover = hansen.select('treecover2000');
    var lossYear = hansen.select('lossyear');
    // For 2003: mask loss up to 2003 (lossYear 1-3)
    var lossMask2003 = lossYear.gt(0).and(lossYear.lte(3));
    var treeCover2003 = treeCover.updateMask(lossMask2003.eq(0));
    forest2003 = treeCover2003.gt(30).selfMask();
    // For 2023: mask loss up to 2022 (lossYear 1-22)
    var lossMask2023 = lossYear.gt(0).and(lossYear.lte(22));
    var treeCover2023 = treeCover.updateMask(lossMask2023.eq(0));
    forest2023 = treeCover2023.gt(30).selfMask();
  }

  // 4. Count forest pixels for each year
  var count2003 = forest2003.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('LC_Type1' || 'treecover2000'); // Band name differs
  var count2023 = forest2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('LC_Type1' || 'treecover2000');

  // Get values (handle potential nulls)
  var val2003 = ee.Number(count2003).getInfo();
  var val2023 = ee.Number(count2023).getInfo();

  console.log(`2003 forest pixels: ${val2003}`);
  console.log(`2023 forest pixels: ${val2023}`);

  // 5. Validation and answer
  if (val2003 === null || val2023 === null || 
      isNaN(val2003) || isNaN(val2023) || 
      val2003 === undefined || val2023 === undefined) {
    console.log('<answer>C3</answer>');
  } else if (val2003 === 0 || val2023 === 0) {
    console.log('<answer>C2</answer>');
  } else if (val2023 < val2003) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
